import { useCallback, useEffect, useMemo, useState } from 'react';
import type { FormEvent, ReactNode } from 'react';
import { io, Socket } from 'socket.io-client';
import {
  Activity, ArrowDownUp, Bell, BookOpen, Boxes, ChefHat, ChevronDown, CircleDollarSign,
  ClipboardList, FileBarChart2, LayoutDashboard, LogOut, Menu, MonitorCog, Package,
  Plus, RefreshCw, ShieldCheck, Store, Users, Utensils, X,
} from 'lucide-react';
import { api, getAccessToken, messageOf, setAccessToken } from './api';
import { money, normalizeStatus } from './utils';

type User = { id:number; nombre:string; correo:string; rol:string; rol_id:number; sucursal_id:number; sucursal:string; activo:boolean; permisos:string[] };
type Product = {id:number; categoria_id:number; categoria:string; nombre:string; precio:number; imagen_url:string; activo:boolean};
type TableData = {id:number; sucursal_id:number; numero:number; capacidad:number; estado:string};
type OrderLine = {id:number; producto_id:number; producto:string; cantidad:number; precio_unitario:number; subtotal:number; notas:string; estado:string};
type Order = {id:number; sucursal_id:number; mesa_id:number; mesa_numero:number; mesero_id:number; estado:string; total:number; pagado:number; pendiente:number; fecha:string; detalles:OrderLine[]};
type Ingredient = {id:number; nombre:string; unidad_medida:string};
type Stock = {id:number; sucursal_id:number; insumo_id:number; existencia:number; stock_minimo:number; insumo:string; unidad_medida:string; stock_bajo:boolean};
type Category = {id:number; nombre:string};
type Role = {id:number; nombre:string; permisos:{id:number;clave:string;descripcion:string}[]};
type Permission = {id:number;clave:string;descripcion:string};

function dateTime(v: string) { return new Date(v).toLocaleString('es-MX',{dateStyle:'short',timeStyle:'short'}); }
function Status({value}: {value:string}) { const s=normalizeStatus(value); return <span className={`status status-${s}`}>{value.replaceAll('_',' ')}</span>; }
function Card({children,className=''}:{children:ReactNode;className?:string}) { return <section className={`card ${className}`}>{children}</section>; }
function PageTitle({eyebrow,title,description,action}:{eyebrow:string;title:string;description:string;action?:ReactNode}) { return <div className="page-title"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{description}</p></div>{action}</div>; }
function Empty({title,detail}:{title:string;detail:string}) { return <div className="empty"><Package size={28}/><strong>{title}</strong><span>{detail}</span></div>; }
function ErrorBanner({error}:{error:string}) { return error ? <div className="alert alert-error" role="alert">{error}</div> : null; }
function SuccessBanner({message}:{message:string}) { return message ? <div className="alert alert-success" role="status">{message}</div> : null; }

function Login({onLogin}:{onLogin:(email:string,password:string)=>Promise<void>}) {
  const [email,setEmail]=useState('admin@comandapro.local'); const [password,setPassword]=useState(''); const [busy,setBusy]=useState(false); const [error,setError]=useState('');
  async function submit(e:FormEvent){ e.preventDefault();setBusy(true);setError('');try{await onLogin(email,password)}catch(ex){setError(messageOf(ex))}finally{setBusy(false)} }
  return <div className="login-shell"><div className="login-art"><div className="brand brand-large"><span className="brand-mark"><Utensils/></span><span>comanda<span className="brand-soft">pro</span></span></div><div className="login-art-copy"><div className="eyebrow eyebrow-light">OPERACIÓN RESTAURANTERA · EN TIEMPO REAL</div><h1>De la mesa<br/>a la cocina,<br/><em>sin perder el ritmo.</em></h1><p>Comandas sincronizadas, ingredientes bajo control y cuentas claras en cada sucursal.</p></div><div className="art-bottom"><span>3 sucursales</span><span>·</span><span>4 roles</span><span>·</span><span>Inventario conectado</span></div></div><div className="login-panel"><div className="login-form"><div className="eyebrow">BIENVENIDO DE VUELTA</div><h2>Inicia sesión</h2><p>Accede al espacio de tu sucursal.</p><form onSubmit={submit}><label>Correo electrónico<input type="email" autoComplete="username" value={email} onChange={e=>setEmail(e.target.value)} required/></label><label>Contraseña<input type="password" autoComplete="current-password" value={password} onChange={e=>setPassword(e.target.value)} required/></label><ErrorBanner error={error}/><button className="btn btn-primary btn-full" disabled={busy}>{busy?'Verificando…':'Entrar a ComandaPro'}</button></form><div className="demo-note"><strong>Accesos de demostración</strong><span>ADMIN: admin@comandapro.local</span><span>MESERO: mesero@comandapro.local</span><span>COCINA: cocina@comandapro.local</span><span>CAJERO: cajero@comandapro.local</span><small>Contraseña inicial común de demo: DemoComanda2026! (ADMIN usa la definida en .env).</small></div></div><div className="login-footer">ComandaPro · Proyecto académico · UTNG</div></div></div>;
}

function Dashboard({user,onNavigate,version}:{user:User;onNavigate:(v:string)=>void;version:number}) {
  const [orders,setOrders]=useState<Order[]>([]); const [tables,setTables]=useState<TableData[]>([]); const [stock,setStock]=useState<Stock[]>([]); const [sales,setSales]=useState<{sucursal:string;ventas:number;pagos:number}[]>([]); const [error,setError]=useState('');
  const load=useCallback(async()=>{setError('');const [o,t,s,r]=await Promise.allSettled([api.get('/ordenes'),api.get('/mesas'),api.get('/reportes/stock-bajo'),api.get('/reportes/ventas')]);if(o.status==='fulfilled')setOrders(o.value.data);if(t.status==='fulfilled')setTables(t.value.data);if(s.status==='fulfilled')setStock(s.value.data);if(r.status==='fulfilled')setSales(r.value.data);const fail=[o,t,s,r].find(x=>x.status==='rejected');if(fail&&fail.status==='rejected')setError('Algunos indicadores están ocultos por los permisos de tu rol.');},[]);
  useEffect(()=>{void load()},[load,version]);
  const liveOrders=orders.filter(o=>['ABIERTA','EN_COCINA','SERVIDA'].includes(o.estado));const totalSales=sales.reduce((a,x)=>a+x.ventas,0);
  return <><PageTitle eyebrow={`SUCURSAL · ${user.sucursal}`} title={`Buen día, ${user.nombre.split(' ')[0]}`} description="Este es el pulso operativo de tu restaurante." action={<button className="btn btn-secondary" onClick={()=>void load()}><RefreshCw size={16}/> Actualizar</button>}/><ErrorBanner error={error}/><div className="metric-grid"><div className="metric-card"><div className="metric-icon icon-green"><ClipboardList/></div><span>Órdenes activas</span><strong>{liveOrders.length}</strong><small>{orders.filter(o=>o.estado==='EN_COCINA').length} en cocina ahora</small></div><div className="metric-card"><div className="metric-icon icon-orange"><Utensils/></div><span>Mesas ocupadas</span><strong>{tables.filter(t=>t.estado==='OCUPADA').length}<small className="metric-total"> / {tables.length}</small></strong><small>Ocupación de la sucursal</small></div><div className="metric-card"><div className="metric-icon icon-blue"><CircleDollarSign/></div><span>Ventas registradas</span><strong>{money(totalSales)}</strong><small>{sales.reduce((a,x)=>a+x.pagos,0)} pagos contabilizados</small></div><div className="metric-card"><div className="metric-icon icon-red"><Package/></div><span>Alertas de inventario</span><strong>{stock.length}</strong><small>Insumos bajo su mínimo</small></div></div><div className="dashboard-grid"><Card><div className="card-heading"><div><h2>Órdenes en curso</h2><p>Actualización de la operación</p></div><button className="text-button" onClick={()=>onNavigate('ordenes')}>Ver órdenes →</button></div>{liveOrders.length? <div className="order-list">{liveOrders.slice(0,6).map(o=><div className="order-row" key={o.id}><div className="order-number"><strong>#{String(o.id).padStart(4,'0')}</strong><span>Mesa {o.mesa_numero}</span></div><div className="order-content"><strong>{o.detalles.filter(d=>d.estado!=='CANCELADO').length} platillos</strong><span>{dateTime(o.fecha)}</span></div><Status value={o.estado}/><strong className="amount">{money(o.total)}</strong></div>)}</div>:<Empty title="No hay órdenes activas" detail="Las nuevas comandas aparecerán aquí."/>}</Card><Card><div className="card-heading"><div><h2>Accesos rápidos</h2><p>Lo que necesitas, en un clic</p></div></div><div className="quick-grid">{user.permisos.includes('ordenes.crear')&&<button onClick={()=>onNavigate('ordenes')}><span className="quick-icon"><Plus/></span><strong>Nueva orden</strong><small>Tomar pedido desde mesa</small></button>}{user.permisos.includes('cocina.ver')&&<button onClick={()=>onNavigate('cocina')}><span className="quick-icon"><ChefHat/></span><strong>Vista de cocina</strong><small>Preparación en tiempo real</small></button>}{user.permisos.includes('pagos.ver')&&<button onClick={()=>onNavigate('caja')}><span className="quick-icon"><CircleDollarSign/></span><strong>Caja</strong><small>Cuentas y pagos divididos</small></button>}{user.permisos.includes('inventario.ver')&&<button onClick={()=>onNavigate('inventario')}><span className="quick-icon"><Boxes/></span><strong>Inventario</strong><small>Stock por insumo</small></button>}</div></Card></div><Card><div className="card-heading"><div><h2>Estado de mesas</h2><p>Distribución de la sucursal</p></div><button className="text-button" onClick={()=>onNavigate('ordenes')}>Abrir mapa →</button></div><div className="table-chips">{tables.slice(0,12).map(t=><button className={`table-chip ${t.estado==='OCUPADA'?'occupied':t.estado==='RESERVADA'?'reserved':''}`} key={t.id} onClick={()=>onNavigate('ordenes')}><span>{t.numero}</span><small>{t.estado}</small></button>)}</div></Card></>;
}

function OrdersPage({user,notify,version}:{user:User;notify:(s:string)=>void;version:number}) {
  const [tables,setTables]=useState<TableData[]>([]);const [products,setProducts]=useState<Product[]>([]);const [orders,setOrders]=useState<Order[]>([]);const [cart,setCart]=useState<{producto_id:number;cantidad:number;notas:string}[]>([]);const [tableId,setTableId]=useState<number>(0);const [productId,setProductId]=useState<number>(0);const [quantity,setQuantity]=useState(1);const [notes,setNotes]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false);const [newTableNumber,setNewTableNumber]=useState('13');const [newTableCapacity,setNewTableCapacity]=useState('4');const [tableBusy,setTableBusy]=useState(0);
  const load=useCallback(async()=>{try{const [t,p,o]=await Promise.all([api.get('/mesas'),api.get('/productos'),api.get('/ordenes')]);setTables(t.data);setProducts(p.data);setOrders(o.data);if(!tableId){const available=t.data.find((x:TableData)=>x.estado==='LIBRE');if(available)setTableId(available.id)}if(!productId&&p.data[0])setProductId(p.data[0].id)}catch(e){setError(messageOf(e))}},[tableId,productId]);
  useEffect(()=>{void load()},[load,version]);
  const selectedTable=tables.find(t=>t.id===tableId);const cartTotal=cart.reduce((a,line)=>a+(products.find(p=>p.id===line.producto_id)?.precio||0)*line.cantidad,0);
  function addCart(){if(!productId)return;setCart(prev=>[...prev,{producto_id:productId,cantidad:quantity,notas:notes}]);setNotes('');setQuantity(1)}
  async function createOrder(){if(!tableId||cart.length===0){setError('Selecciona una mesa libre y agrega al menos un platillo.');return}setBusy(true);setError('');try{await api.post('/ordenes',{mesa_id:tableId,detalles:cart});setCart([]);notify('Orden creada y asignada a la mesa.');await load()}catch(e){setError(messageOf(e))}finally{setBusy(false)}}
  async function orderAction(id:number,action:'enviar-cocina'|'servir'|'cancelar'){try{if(action==='cancelar')await api.post(`/ordenes/${id}/cancelar`,{motivo:'Cancelación desde la interfaz'});else await api.post(`/ordenes/${id}/${action}`);notify(action==='enviar-cocina'?'Comanda enviada a cocina':action==='servir'?'Orden marcada como servida':'Orden cancelada');await load()}catch(e){setError(messageOf(e))}}
  async function createTable(e:FormEvent){e.preventDefault();setTableBusy(-1);try{await api.post('/mesas',{numero:Number(newTableNumber),capacidad:Number(newTableCapacity),estado:'LIBRE'});notify('Mesa creada');await load()}catch(e){setError(messageOf(e))}finally{setTableBusy(0)}}
  async function updateTableState(table:TableData,state:string){setTableBusy(table.id);try{await api.patch(`/mesas/${table.id}`,{numero:table.numero,capacidad:table.capacidad,estado:state});notify(`Mesa ${table.numero}: ${state.toLowerCase()}`);await load()}catch(e){setError(messageOf(e))}finally{setTableBusy(0)}}
  async function deleteTable(table:TableData){if(!window.confirm(`¿Eliminar la mesa ${table.numero}? Solo se puede borrar si no tiene órdenes activas ni historial asociado.`))return;setTableBusy(table.id);try{await api.delete(`/mesas/${table.id}`);notify('Mesa eliminada');await load()}catch(e){setError(messageOf(e))}finally{setTableBusy(0)}}
  return <><PageTitle eyebrow="OPERACIÓN DE SALÓN" title="Mesas y órdenes" description="Toma pedidos, envía comandas a cocina y sigue su estado." action={<button className="btn btn-secondary" onClick={()=>void load()}><RefreshCw size={16}/> Actualizar</button>}/><ErrorBanner error={error}/><div className="work-grid"><Card><div className="card-heading"><div><h2>Nueva comanda</h2><p>Solo se muestran mesas de {user.sucursal}.</p></div><span className="pill">{tables.filter(t=>t.estado==='LIBRE').length} mesas libres</span></div><label>Mesa<select value={tableId} onChange={e=>setTableId(Number(e.target.value))}><option value={0}>Seleccionar mesa…</option>{tables.filter(t=>t.estado==='LIBRE'||t.id===tableId).map(t=><option value={t.id} key={t.id}>Mesa {t.numero} · {t.capacidad} personas · {t.estado}</option>)}</select></label><div className="field-row"><label className="grow">Platillo<select value={productId} onChange={e=>setProductId(Number(e.target.value))}>{products.map(p=><option key={p.id} value={p.id}>{p.nombre} · {money(p.precio)}</option>)}</select></label><label className="quantity-field">Cantidad<input type="number" min="1" max="100" value={quantity} onChange={e=>setQuantity(Math.max(1,Math.min(100,Number(e.target.value))))}/></label></div><label>Nota para cocina<input value={notes} onChange={e=>setNotes(e.target.value)} placeholder="Sin cebolla, término medio…" maxLength={300}/></label><button className="btn btn-secondary btn-full" onClick={addCart} disabled={!productId}><Plus size={16}/> Agregar platillo</button>{cart.length>0&&<div className="cart-list"><div className="card-heading"><h3>Detalle de la orden</h3><button className="text-button" onClick={()=>setCart([])}>Vaciar</button></div>{cart.map((line,i)=>{const product=products.find(p=>p.id===line.producto_id);return <div className="cart-line" key={i}><div><strong>{product?.nombre}</strong><small>{line.cantidad} × {money(product?.precio)} {line.notas&&`· ${line.notas}`}</small></div><strong>{money((product?.precio||0)*line.cantidad)}</strong><button className="icon-button" aria-label="Quitar" onClick={()=>setCart(prev=>prev.filter((_,idx)=>idx!==i))}><X size={15}/></button></div>})}<div className="cart-total"><span>Total estimado</span><strong>{money(cartTotal)}</strong></div><button className="btn btn-primary btn-full" onClick={()=>void createOrder()} disabled={busy||!selectedTable}>{busy?'Guardando…':'Crear orden'}</button></div>}</Card><Card><div className="card-heading"><div><h2>Actividad reciente</h2><p>Órdenes de tu sucursal</p></div><span className="pill">{orders.length} registros</span></div>{orders.length===0?<Empty title="Aún no hay órdenes" detail="Crea la primera desde el formulario."/>:<div className="order-list">{orders.slice(0,30).map(o=><div className="order-card" key={o.id}><div className="order-card-top"><div className="order-number"><strong>#{String(o.id).padStart(4,'0')}</strong><span>Mesa {o.mesa_numero} · {dateTime(o.fecha)}</span></div><Status value={o.estado}/></div><div className="order-products">{o.detalles.map(d=><div className="mini-detail" key={d.id}><span>{d.cantidad} × {d.producto}</span><div className="mini-detail-actions"><Status value={d.estado}/>{o.estado==='ABIERTA'&&user.permisos.includes('ordenes.editar')&&d.estado!=='CANCELADO'&&<button className="text-button" onClick={async()=>{const value=window.prompt(`Cantidad para ${d.producto}:`,String(d.cantidad));if(value===null)return;const cantidad=Number(value);if(!Number.isInteger(cantidad)||cantidad<1||cantidad>100){setError('La cantidad debe ser un entero entre 1 y 100.');return}try{await api.patch(`/ordenes/${o.id}/detalles/${d.id}`,{cantidad});notify('Detalle actualizado');await load()}catch(e){setError(messageOf(e))}}}>Editar</button>}</div></div>)}</div><div className="order-actions"><strong>{money(o.total)}</strong>{o.estado==='ABIERTA'&&user.permisos.includes('ordenes.enviar_cocina')&&<button className="btn btn-small btn-primary" onClick={()=>void orderAction(o.id,'enviar-cocina')}>Enviar a cocina</button>}{o.estado==='EN_COCINA'&&user.permisos.includes('ordenes.editar')&&<button className="btn btn-small btn-secondary" onClick={()=>void orderAction(o.id,'servir')} disabled={o.detalles.some(d=>d.estado!=='LISTO'&&d.estado!=='CANCELADO')}>Marcar servida</button>}{['ABIERTA','EN_COCINA'].includes(o.estado)&&user.permisos.includes('ordenes.cancelar')&&<button className="btn btn-small btn-danger" onClick={()=>void orderAction(o.id,'cancelar')}>Cancelar</button>}</div></div>)}</div>}</Card></div>{user.permisos.includes('mesas.configurar')&&<Card className="table-admin"><div className="card-heading"><div><h2>Administración de mesas</h2><p>Alta, estado y baja de mesas de la sucursal actual.</p></div><span className="pill">{tables.length} mesas</span></div><form className="table-create-form" onSubmit={createTable}><label>Número de mesa<input type="number" min="1" max="1000" value={newTableNumber} onChange={e=>setNewTableNumber(e.target.value)} required/></label><label>Capacidad<input type="number" min="1" max="30" value={newTableCapacity} onChange={e=>setNewTableCapacity(e.target.value)} required/></label><button className="btn btn-primary" disabled={tableBusy===-1}><Plus size={15}/> Crear mesa</button></form><div className="table-responsive"><table><thead><tr><th>Mesa</th><th>Capacidad</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>{tables.map(t=><tr key={t.id}><td><strong>#{t.numero}</strong></td><td>{t.capacidad} personas</td><td><select className="small-select" value={t.estado} disabled={tableBusy===t.id} onChange={e=>void updateTableState(t,e.target.value)}><option>LIBRE</option><option>OCUPADA</option><option>RESERVADA</option></select></td><td><button className="btn btn-small btn-danger" disabled={tableBusy===t.id} onClick={()=>void deleteTable(t)}>Eliminar</button></td></tr>)}</tbody></table></div></Card>}</>;
}

function KitchenPage({notify,version}:{notify:(s:string)=>void;version:number}) {
  const [orders,setOrders]=useState<Order[]>([]);const [error,setError]=useState('');const [busyId,setBusyId]=useState(0);
  const load=useCallback(async()=>{try{const r=await api.get('/cocina/ordenes');setOrders(r.data);setError('')}catch(e){setError(messageOf(e))}},[]);useEffect(()=>{void load()},[load,version]);
  async function setDish(detail:OrderLine,state:'PREPARANDO'|'LISTO'){setBusyId(detail.id);setError('');try{await api.patch(`/cocina/detalles/${detail.id}/estado`,{estado:state});notify(`${detail.producto}: ${state==='LISTO'?'listo para servir':'en preparación'}`);await load()}catch(e){setError(messageOf(e))}finally{setBusyId(0)}}
  return <><PageTitle eyebrow="PASE DE COCINA · EN VIVO" title="Comandas de cocina" description="Las órdenes se transmiten al instante por la sala de Socket.IO de tu sucursal." action={<button className="btn btn-secondary" onClick={()=>void load()}><RefreshCw size={16}/> Actualizar</button>}/><ErrorBanner error={error}/><div className="kanban"><div className="kanban-column"><div className="kanban-head"><span className="kanban-dot dot-pending"/><strong>Por preparar</strong><span>{orders.reduce((a,o)=>a+o.detalles.filter(d=>d.estado==='PENDIENTE').length,0)}</span></div>{orders.flatMap(o=>o.detalles.filter(d=>d.estado==='PENDIENTE').map(d=>({o,d}))).map(({o,d})=><div className="dish-card" key={d.id}><div className="dish-meta"><span>ORDEN #{o.id} · MESA {o.mesa_numero}</span><span>{d.cantidad}×</span></div><h3>{d.producto}</h3>{d.notas&&<p className="dish-note">“{d.notas}”</p>}<button className="btn btn-primary btn-full" disabled={busyId===d.id} onClick={()=>void setDish(d,'PREPARANDO')}>Comenzar preparación →</button></div>)}</div><div className="kanban-column"><div className="kanban-head"><span className="kanban-dot dot-cooking"/><strong>Preparando</strong><span>{orders.reduce((a,o)=>a+o.detalles.filter(d=>d.estado==='PREPARANDO').length,0)}</span></div>{orders.flatMap(o=>o.detalles.filter(d=>d.estado==='PREPARANDO').map(d=>({o,d}))).map(({o,d})=><div className="dish-card" key={d.id}><div className="dish-meta"><span>ORDEN #{o.id} · MESA {o.mesa_numero}</span><span>{d.cantidad}×</span></div><h3>{d.producto}</h3>{d.notas&&<p className="dish-note">“{d.notas}”</p>}<button className="btn btn-primary btn-full" disabled={busyId===d.id} onClick={()=>void setDish(d,'LISTO')}>Marcar listo ✓</button></div>)}</div><div className="kanban-column"><div className="kanban-head"><span className="kanban-dot dot-ready"/><strong>Listos</strong><span>{orders.reduce((a,o)=>a+o.detalles.filter(d=>d.estado==='LISTO').length,0)}</span></div>{orders.flatMap(o=>o.detalles.filter(d=>d.estado==='LISTO').map(d=>({o,d}))).map(({o,d})=><div className="dish-card dish-ready" key={d.id}><div className="dish-meta"><span>ORDEN #{o.id} · MESA {o.mesa_numero}</span><span>{d.cantidad}×</span></div><h3>{d.producto}</h3><div className="ready-note">✓ Aviso enviado al salón</div></div>)}</div></div></>;
}

function CashierPage({notify,version}:{notify:(s:string)=>void;version:number}) {
  const [orders,setOrders]=useState<Order[]>([]);const [amounts,setAmounts]=useState<Record<number,string>>({});const [methods,setMethods]=useState<Record<number,string>>({});const [error,setError]=useState('');const [busy,setBusy]=useState(0);
  const load=useCallback(async()=>{try{const r=await api.get('/pagos/ordenes-abiertas');setOrders(r.data);setError('')}catch(e){setError(messageOf(e))}},[]);useEffect(()=>{void load()},[load,version]);
  async function pay(o:Order){setBusy(o.id);setError('');try{const amount=Number(amounts[o.id]||o.pendiente);const r=await api.post(`/ordenes/${o.id}/pagos`,{metodo:methods[o.id]||'EFECTIVO',monto:amount});notify(r.data.cerrada?`Orden #${o.id} pagada y mesa liberada`:`Abono registrado. Saldo: ${money(r.data.saldo)}`);await load()}catch(e){setError(messageOf(e))}finally{setBusy(0)}}
  return <><PageTitle eyebrow="CAJA · COBRO" title="Cuentas por cobrar" description="Registra un pago completo o divide la cuenta entre varios métodos/personas." action={<button className="btn btn-secondary" onClick={()=>void load()}><RefreshCw size={16}/> Actualizar</button>}/><ErrorBanner error={error}/>{orders.length===0?<Card><Empty title="No hay cuentas listas para cobrar" detail="Cuando el mesero marque una orden como servida, aparecerá aquí."/></Card>:<div className="cashier-grid">{orders.map(o=><Card key={o.id}><div className="card-heading"><div><h2>Cuenta #{String(o.id).padStart(4,'0')}</h2><p>Mesa {o.mesa_numero} · {dateTime(o.fecha)}</p></div><Status value={o.estado}/></div><div className="pay-lines">{o.detalles.filter(d=>d.estado!=='CANCELADO').map(d=><div key={d.id}><span>{d.cantidad} × {d.producto}</span><span>{money(d.subtotal)}</span></div>)}</div><div className="pay-total"><span>Total</span><strong>{money(o.total)}</strong></div><div className="pay-row"><span>Pagado</span><strong>{money(o.pagado)}</strong></div><div className="pay-row pay-remaining"><span>Saldo pendiente</span><strong>{money(o.pendiente)}</strong></div><label>Método de pago<select value={methods[o.id]||'EFECTIVO'} onChange={e=>setMethods(prev=>({...prev,[o.id]:e.target.value}))}><option>EFECTIVO</option><option>TARJETA</option><option>TRANSFERENCIA</option></select></label><label>Importe de este pago<input type="number" min="0.01" step="0.01" max={o.pendiente} value={amounts[o.id]??String(o.pendiente)} onChange={e=>setAmounts(prev=>({...prev,[o.id]:e.target.value}))}/></label><button className="btn btn-primary btn-full" onClick={()=>void pay(o)} disabled={busy===o.id}>{busy===o.id?'Registrando…':Number(amounts[o.id]??o.pendiente)<o.pendiente?'Registrar abono':'Cobrar y cerrar cuenta'}</button></Card>)}</div>}</>;
}

function InventoryPage({user,notify,version}:{user:User;notify:(s:string)=>void;version:number}) {
  const [rows,setRows]=useState<Stock[]>([]);const [branches,setBranches]=useState<{id:number;nombre:string}[]>([]);const [branch,setBranch]=useState('');const [error,setError]=useState('');const [movement,setMovement]=useState<Record<number,{tipo:string;cantidad:string;nota:string}>>({});const [busy,setBusy]=useState(0);
  const canCompare=user.permisos.includes('sucursales.ver_todas');
  const load=useCallback(async()=>{try{const params=branch?{sucursal_id:Number(branch)}:{};const [r,b]=await Promise.all([api.get('/inventario',{params}),canCompare?api.get('/admin/sucursales'):Promise.resolve({data:[]})]);setRows(r.data);setBranches(b.data);setError('')}catch(e){setError(messageOf(e))}},[branch,canCompare]);useEffect(()=>{void load()},[load,version]);
  async function submit(row:Stock){const m=movement[row.id]||{tipo:'ENTRADA',cantidad:'1',nota:''};setBusy(row.id);try{await api.post(`/inventario/${row.id}/movimientos`,{tipo:m.tipo,cantidad:Number(m.cantidad),nota:m.nota},{params:branch?{sucursal_id:Number(branch)}:{}});notify(`Movimiento de ${row.insumo} registrado`);await load()}catch(e){setError(messageOf(e))}finally{setBusy(0)}}
  return <><PageTitle eyebrow="ABASTO · CONTROL DE INSUMOS" title="Inventario de sucursal" description="Las existencias se ajustan por sucursal; los consumos de recetas quedan en la bitácora de movimientos." action={<button className="btn btn-secondary" onClick={()=>void load()}><RefreshCw size={16}/> Actualizar</button>}/><ErrorBanner error={error}/>{canCompare&&<Card className="filter-card"><label className="filter-label">Sucursal<select value={branch} onChange={e=>setBranch(e.target.value)}><option value="">Mi sucursal ({user.sucursal})</option>{branches.map(b=><option value={b.id} key={b.id}>{b.nombre}</option>)}</select></label><p className="muted">Los movimientos manuales se registran a nombre del usuario que los realiza.</p></Card>}<Card><div className="table-responsive"><table><thead><tr><th>Insumo</th><th>Existencia</th><th>Mínimo</th><th>Estado</th><th>Movimiento manual</th></tr></thead><tbody>{rows.map(r=>{const m=movement[r.id]||{tipo:'ENTRADA',cantidad:'1',nota:''};return <tr key={r.id}><td><strong>{r.insumo}</strong><small className="cell-sub">Unidad: {r.unidad_medida}</small></td><td className="stock-number">{Number(r.existencia).toLocaleString('es-MX',{maximumFractionDigits:3})}</td><td>{Number(r.stock_minimo).toLocaleString('es-MX')}</td><td>{r.stock_bajo?<Status value="STOCK_BAJO"/>:<Status value="DISPONIBLE"/>}</td><td><div className="inline-movement"><select value={m.tipo} onChange={e=>setMovement(p=>({...p,[r.id]:{...m,tipo:e.target.value}}))}><option>ENTRADA</option><option>AJUSTE_POSITIVO</option><option>AJUSTE_NEGATIVO</option></select><input aria-label="Cantidad movimiento" type="number" min="0.001" step="0.001" value={m.cantidad} onChange={e=>setMovement(p=>({...p,[r.id]:{...m,cantidad:e.target.value}}))}/><button className="btn btn-small btn-secondary" disabled={busy===r.id} onClick={()=>void submit(r)}>Aplicar</button></div></td></tr>})}</tbody></table></div>{rows.length===0&&<Empty title="Sin insumos" detail="Revisa los permisos y vuelve a cargar."/>}</Card></>;
}

function MenuAdmin({notify,version}:{notify:(s:string)=>void;version:number}) {
  const [categories,setCategories]=useState<Category[]>([]);const [products,setProducts]=useState<Product[]>([]);const [ingredients,setIngredients]=useState<Ingredient[]>([]);const [tab,setTab]=useState<'productos'|'categorias'|'recetas'|'insumos'>('productos');const [error,setError]=useState('');const [categoryName,setCategoryName]=useState('');const [product,setProduct]=useState({nombre:'',categoria_id:0,precio:'',imagen_url:''});const [ingredient,setIngredient]=useState({nombre:'',unidad_medida:'pieza'});const [selectedProduct,setSelectedProduct]=useState(0);const [recipeLines,setRecipeLines]=useState<{insumo_id:number;cantidad:string}[]>([]);
  const load=useCallback(async()=>{try{const [c,p,i]=await Promise.all([api.get('/categorias'),api.get('/productos?activos=false'),api.get('/insumos')]);setCategories(c.data);setProducts(p.data);setIngredients(i.data);if(!product.categoria_id&&c.data[0])setProduct(x=>({...x,categoria_id:c.data[0].id}));if(!selectedProduct&&p.data[0])setSelectedProduct(p.data[0].id);setError('')}catch(e){setError(messageOf(e))}},[product.categoria_id,selectedProduct]);useEffect(()=>{void load()},[load,version]);
  useEffect(()=>{if(selectedProduct)api.get(`/productos/${selectedProduct}/receta`).then(r=>setRecipeLines(r.data.map((x:{insumo_id:number;cantidad:number})=>({insumo_id:x.insumo_id,cantidad:String(x.cantidad)})))).catch(()=>setRecipeLines([]))},[selectedProduct,version]);
  async function createCategory(e:FormEvent){e.preventDefault();try{await api.post('/categorias',{nombre:categoryName});setCategoryName('');notify('Categoría creada');await load()}catch(ex){setError(messageOf(ex))}}
  async function createProduct(e:FormEvent){e.preventDefault();try{await api.post('/productos',{...product,precio:Number(product.precio),activo:true});setProduct(x=>({...x,nombre:'',precio:'',imagen_url:''}));notify('Producto creado');await load()}catch(ex){setError(messageOf(ex))}}
  async function createIngredient(e:FormEvent){e.preventDefault();try{await api.post('/insumos',ingredient);setIngredient({nombre:'',unidad_medida:'pieza'});notify('Insumo creado');await load()}catch(ex){setError(messageOf(ex))}}
  async function saveRecipe(){try{await api.put(`/productos/${selectedProduct}/receta`,{insumos:recipeLines.map(x=>({insumo_id:x.insumo_id,cantidad:Number(x.cantidad)}))});notify('Receta guardada');await load()}catch(ex){setError(messageOf(ex))}}
  return <><PageTitle eyebrow="CATÁLOGO · CONFIGURACIÓN" title="Menú y recetas" description="Administra categorías, productos, ingredientes y cantidades consumidas por platillo."/><ErrorBanner error={error}/><div className="tabs">{(['productos','categorias','recetas','insumos'] as const).map(t=><button className={tab===t?'active':''} key={t} onClick={()=>setTab(t)}>{t==='productos'?'Productos':t==='categorias'?'Categorías':t==='recetas'?'Recetas':'Insumos'}</button>)}</div>{tab==='categorias'&&<div className="work-grid"><Card><h2>Nueva categoría</h2><form onSubmit={createCategory}><label>Nombre<input value={categoryName} onChange={e=>setCategoryName(e.target.value)} required minLength={2}/></label><button className="btn btn-primary"><Plus size={16}/> Crear categoría</button></form></Card><Card><h2>Categorías registradas</h2><div className="simple-list">{categories.map(c=><div key={c.id}><span><strong>{c.nombre}</strong><small>ID {c.id}</small></span><button className="btn btn-small btn-secondary" onClick={async()=>{const nombre=window.prompt('Nombre de categoría:',c.nombre);if(!nombre)return;try{await api.patch(`/categorias/${c.id}`,{nombre});notify('Categoría actualizada');await load()}catch(e){setError(messageOf(e))}}}>Editar</button><button className="btn btn-small btn-danger" onClick={async()=>{if(!window.confirm(`¿Eliminar categoría ${c.nombre}?`))return;try{await api.delete(`/categorias/${c.id}`);notify('Categoría eliminada');await load()}catch(e){setError(messageOf(e))}}}>Eliminar</button></div>)}</div></Card></div>}{tab==='productos'&&<div className="work-grid"><Card><h2>Nuevo producto</h2><form onSubmit={createProduct}><label>Nombre<input value={product.nombre} onChange={e=>setProduct(p=>({...p,nombre:e.target.value}))} required/></label><label>Categoría<select value={product.categoria_id} onChange={e=>setProduct(p=>({...p,categoria_id:Number(e.target.value)}))} required>{categories.map(c=><option key={c.id} value={c.id}>{c.nombre}</option>)}</select></label><label>Precio (MXN)<input type="number" min="0.01" step="0.01" value={product.precio} onChange={e=>setProduct(p=>({...p,precio:e.target.value}))} required/></label><label>Imagen URL (opcional)<input value={product.imagen_url} onChange={e=>setProduct(p=>({...p,imagen_url:e.target.value}))}/></label><button className="btn btn-primary"><Plus size={16}/> Guardar producto</button></form></Card><Card><h2>Menú de productos</h2><div className="simple-list">{products.map(p=><div key={p.id}><span><strong>{p.nombre}</strong><small>{p.categoria}</small></span><strong>{money(p.precio)}</strong><button className="btn btn-small btn-secondary" onClick={async()=>{const nombre=window.prompt('Nombre del producto:',p.nombre);if(nombre===null)return;const precio=window.prompt('Precio MXN:',String(p.precio));if(precio===null)return;try{await api.patch(`/productos/${p.id}`,{categoria_id:p.categoria_id,nombre,precio:Number(precio),imagen_url:p.imagen_url||'',activo:p.activo});notify('Producto actualizado');await load()}catch(e){setError(messageOf(e))}}}>Editar</button>{p.activo&&<button className="btn btn-small btn-danger" onClick={async()=>{try{await api.delete(`/productos/${p.id}`);notify('Producto desactivado');await load()}catch(e){setError(messageOf(e))}}}>Desactivar</button>}</div>)}</div></Card></div>}{tab==='recetas'&&<Card><h2>Configuración de receta</h2><p className="muted">Define la cantidad de cada insumo que se descontará al enviar un producto a cocina.</p><label>Producto<select value={selectedProduct} onChange={e=>setSelectedProduct(Number(e.target.value))}>{products.filter(p=>p.activo).map(p=><option value={p.id} key={p.id}>{p.nombre}</option>)}</select></label><div className="recipe-list">{recipeLines.map((r,i)=><div className="field-row recipe-line" key={i}><label className="grow">Insumo<select value={r.insumo_id} onChange={e=>setRecipeLines(x=>x.map((v,j)=>i===j?{...v,insumo_id:Number(e.target.value)}:v))}>{ingredients.map(it=><option key={it.id} value={it.id}>{it.nombre} ({it.unidad_medida})</option>)}</select></label><label>Cantidad por platillo<input type="number" min="0.001" step="0.001" value={r.cantidad} onChange={e=>setRecipeLines(x=>x.map((v,j)=>i===j?{...v,cantidad:e.target.value}:v))}/></label><button className="icon-button" aria-label="Quitar ingrediente" onClick={()=>setRecipeLines(x=>x.filter((_,j)=>j!==i))}><X size={16}/></button></div>)}</div><div className="button-row"><button className="btn btn-secondary" onClick={()=>ingredients[0]&&setRecipeLines(x=>[...x,{insumo_id:ingredients[0].id,cantidad:'0.100'}])}><Plus size={16}/> Agregar insumo</button><button className="btn btn-primary" onClick={()=>void saveRecipe()} disabled={!selectedProduct||recipeLines.length===0}>Guardar receta</button></div></Card>}{tab==='insumos'&&<div className="work-grid"><Card><h2>Nuevo insumo</h2><form onSubmit={createIngredient}><label>Nombre<input value={ingredient.nombre} onChange={e=>setIngredient(p=>({...p,nombre:e.target.value}))} required/></label><label>Unidad<select value={ingredient.unidad_medida} onChange={e=>setIngredient(p=>({...p,unidad_medida:e.target.value}))}><option>pieza</option><option>kg</option><option>g</option><option>litro</option><option>ml</option><option>porción</option></select></label><button className="btn btn-primary"><Plus size={16}/> Crear insumo</button></form></Card><Card><h2>Insumos</h2><div className="simple-list">{ingredients.map(x=><div key={x.id}><span><strong>{x.nombre}</strong><small>{x.unidad_medida}</small></span><button className="btn btn-small btn-secondary" onClick={async()=>{const nombre=window.prompt('Nombre del insumo:',x.nombre);if(nombre===null)return;const unidad_medida=window.prompt('Unidad de medida:',x.unidad_medida);if(unidad_medida===null)return;try{await api.patch(`/insumos/${x.id}`,{nombre,unidad_medida});notify('Insumo actualizado');await load()}catch(e){setError(messageOf(e))}}}>Editar</button></div>)}</div></Card></div>}</>;
}

function SecurityAdmin({user,notify,version}:{user:User;notify:(s:string)=>void;version:number}) {
  const [tab,setTab]=useState<'usuarios'|'roles'>('usuarios');const [users,setUsers]=useState<User[]>([]);const [roles,setRoles]=useState<Role[]>([]);const [permissions,setPermissions]=useState<Permission[]>([]);const [branches,setBranches]=useState<{id:number;nombre:string}[]>([]);const [error,setError]=useState('');const [newUser,setNewUser]=useState({nombre:'',correo:'',password:'',rol_id:0,sucursal_id:user.sucursal_id});const [selectedRole,setSelectedRole]=useState(0);const [grants,setGrants]=useState<number[]>([]);const [roleName,setRoleName]=useState('');const [permForm,setPermForm]=useState({clave:'',descripcion:''});
  const load=useCallback(async()=>{try{const [u,r,p,b]=await Promise.all([api.get('/admin/usuarios'),api.get('/admin/roles'),api.get('/admin/permisos'),api.get('/admin/sucursales')]);setUsers(u.data);setRoles(r.data);setPermissions(p.data);setBranches(b.data);if(!newUser.rol_id&&r.data[0])setNewUser(x=>({...x,rol_id:r.data[0].id}));if(!newUser.sucursal_id&&b.data[0])setNewUser(x=>({...x,sucursal_id:b.data[0].id}));if(!selectedRole&&r.data[0])setSelectedRole(r.data[0].id);setError('')}catch(e){setError(messageOf(e))}},[newUser.rol_id,newUser.sucursal_id,user.sucursal_id,selectedRole]);useEffect(()=>{void load()},[load,version]);useEffect(()=>{const r=roles.find(x=>x.id===selectedRole);setGrants(r?.permisos.map(p=>p.id)||[])},[roles,selectedRole]);
  async function createUser(e:FormEvent){e.preventDefault();try{await api.post('/admin/usuarios',newUser);setNewUser(p=>({...p,nombre:'',correo:'',password:''}));notify('Usuario creado');await load()}catch(e){setError(messageOf(e))}}
  async function toggleUser(u:User){try{await api.patch(`/admin/usuarios/${u.id}`,{activo:!u.activo});notify(u.activo?'Usuario desactivado':'Usuario activado');await load()}catch(e){setError(messageOf(e))}}
  async function savePermissions(){try{await api.put(`/admin/roles/${selectedRole}/permisos`,{permiso_ids:grants});notify('Matriz de permisos guardada');await load()}catch(e){setError(messageOf(e))}}
  async function createRole(e:FormEvent){e.preventDefault();try{const nombre=roleName.trim().toUpperCase().replace(/\s+/g,'_');const r=await api.post('/admin/roles',{nombre});setSelectedRole(r.data.id);setRoleName('');notify('Rol creado; asigna sus permisos en la matriz');await load()}catch(e){setError(messageOf(e))}}
  async function renameRole(role:Role){const nombre=window.prompt('Nuevo nombre del rol (mayúsculas y guion bajo):',role.nombre);if(!nombre)return;try{await api.patch(`/admin/roles/${role.id}`,{nombre:nombre.trim().toUpperCase().replace(/\s+/g,'_')});notify('Rol actualizado');await load()}catch(e){setError(messageOf(e))}}
  async function deleteRole(role:Role){if(!window.confirm(`¿Eliminar el rol ${role.nombre}? Solo se permite si no tiene usuarios asignados.`))return;try{await api.delete(`/admin/roles/${role.id}`);notify('Rol eliminado');if(selectedRole===role.id)setSelectedRole(0);await load()}catch(e){setError(messageOf(e))}}
  async function createPermission(e:FormEvent){e.preventDefault();try{await api.post('/admin/permisos',permForm);setPermForm({clave:'',descripcion:''});notify('Permiso creado; asigna el nuevo permiso desde la matriz');await load()}catch(e){setError(messageOf(e))}}
  async function deletePermission(permission:Permission){if(!window.confirm(`¿Eliminar el permiso ${permission.clave}? Primero debe quitarse de todos los roles.`))return;try{await api.delete(`/admin/permisos/${permission.id}`);notify('Permiso eliminado');await load()}catch(e){setError(messageOf(e))}}
  return <><PageTitle eyebrow="ADMINISTRACIÓN · SEGURIDAD" title="Usuarios y permisos" description="La autorización se evalúa por permiso en el backend; cada usuario opera dentro de su sucursal."/><ErrorBanner error={error}/><div className="tabs"><button className={tab==='usuarios'?'active':''} onClick={()=>setTab('usuarios')}>Usuarios</button><button className={tab==='roles'?'active':''} onClick={()=>setTab('roles')}>Roles y permisos</button></div>{tab==='usuarios'?<div className="work-grid"><Card><h2>Crear usuario</h2><form onSubmit={createUser}><label>Nombre completo<input value={newUser.nombre} onChange={e=>setNewUser(p=>({...p,nombre:e.target.value}))} required minLength={2}/></label><label>Correo<input type="email" value={newUser.correo} onChange={e=>setNewUser(p=>({...p,correo:e.target.value}))} required/></label><label>Contraseña inicial<input type="password" value={newUser.password} onChange={e=>setNewUser(p=>({...p,password:e.target.value}))} minLength={10} required/></label><label>Rol<select value={newUser.rol_id} onChange={e=>setNewUser(p=>({...p,rol_id:Number(e.target.value)}))}>{roles.map(r=><option key={r.id} value={r.id}>{r.nombre}</option>)}</select></label>{user.permisos.includes('sucursales.ver_todas')&&<label>Sucursal<select value={newUser.sucursal_id} onChange={e=>setNewUser(p=>({...p,sucursal_id:Number(e.target.value)}))}>{branches.map(b=><option key={b.id} value={b.id}>{b.nombre}</option>)}</select></label>}<button className="btn btn-primary"><Plus size={16}/> Crear usuario</button></form></Card><Card><h2>Usuarios por sucursal</h2><p>{user.permisos.includes('usuarios.ver_todas')?'Vista administrativa de usuarios de toda la cadena.':'La lista muestra solo usuarios de la sucursal actual.'}</p><div className="simple-list">{users.map(u=><div key={u.id}><span><strong>{u.nombre}</strong><small>{u.correo} · {u.rol}{u.sucursal?` · ${u.sucursal}`:''}</small></span><button className={`btn btn-small ${u.activo?'btn-danger':'btn-secondary'}`} onClick={()=>void toggleUser(u)}>{u.activo?'Desactivar':'Activar'}</button></div>)}</div></Card></div>:<div className="security-grid"><Card><h2>Crear rol</h2><form onSubmit={createRole}><label>Nombre del rol<input value={roleName} onChange={e=>setRoleName(e.target.value)} placeholder="SUPERVISOR" required pattern="[A-Za-zÁÉÍÓÚÑáéíóúñ_ ]+"/></label><button className="btn btn-secondary"><Plus size={16}/> Añadir rol</button></form><div className="simple-list">{roles.map(r=><div key={r.id}><span><strong>{r.nombre}</strong><small>{r.permisos.length} permisos</small></span><button className="icon-button" aria-label={`Cambiar nombre ${r.nombre}`} onClick={()=>void renameRole(r)} title="Renombrar">✎</button>{r.nombre!=='ADMIN'&&<button className="icon-button" aria-label={`Eliminar ${r.nombre}`} onClick={()=>void deleteRole(r)} title="Eliminar"><X size={15}/></button>}</div>)}</div></Card><Card><div className="field-row"><label className="grow">Matriz de permisos<select value={selectedRole} onChange={e=>setSelectedRole(Number(e.target.value))}>{roles.map(r=><option key={r.id} value={r.id}>{r.nombre}</option>)}</select></label><span className="pill">{grants.length} activos</span></div><div className="permission-grid">{permissions.map(p=><label className="permission-option" key={p.id}><input type="checkbox" checked={grants.includes(p.id)} onChange={e=>setGrants(prev=>e.target.checked?[...prev,p.id]:prev.filter(id=>id!==p.id))}/><span><strong>{p.clave}</strong><small>{p.descripcion}</small></span><button type="button" className="permission-delete" title="Eliminar permiso si no se asignó a roles" onClick={e=>{e.preventDefault();e.stopPropagation();void deletePermission(p)}}><X size={12}/></button></label>)}</div><button className="btn btn-primary" onClick={()=>void savePermissions()}>Guardar matriz de permisos</button></Card><Card className="permission-create"><h2>Crear permiso configurable</h2><form onSubmit={createPermission}><label>Clave (ej. ordenes.exportar)<input value={permForm.clave} onChange={e=>setPermForm(p=>({...p,clave:e.target.value}))} required pattern="[a-z]+([.][a-z0-9_]+)+" placeholder="ordenes.exportar"/></label><label>Descripción<input value={permForm.descripcion} onChange={e=>setPermForm(p=>({...p,descripcion:e.target.value}))} required minLength={3}/></label><button className="btn btn-secondary"><Plus size={16}/> Crear permiso</button></form></Card></div>}</>;
}

function ReportsPage({user,version}:{user:User;version:number}) {
  const [sales,setSales]=useState<{sucursal_id:number;sucursal:string;ventas:number;pagos:number}[]>([]);const [top,setTop]=useState<{producto:string;unidades:number;importe:number}[]>([]);const [low,setLow]=useState<{insumo:string;existencia:number;stock_minimo:number;unidad:string}[]>([]);const [branches,setBranches]=useState<{id:number;nombre:string}[]>([]);const [branch,setBranch]=useState('');const [desde,setDesde]=useState('');const [hasta,setHasta]=useState('');const [error,setError]=useState('');const [exporting,setExporting]=useState(false);const global=user.permisos.includes('reportes.ver_todas');
  const load=useCallback(async()=>{try{const params:Record<string,string>={};if(branch)params.sucursal_id=branch;if(desde)params.desde=`${desde}T00:00:00`;if(hasta)params.hasta=`${hasta}T23:59:59`;const requests=[api.get('/reportes/ventas',{params}),api.get('/reportes/productos-mas-vendidos'),api.get('/reportes/stock-bajo'),global?api.get('/admin/sucursales'):Promise.resolve({data:[]})];const [s,t,l,b]=await Promise.all(requests);setSales(s.data);setTop(t.data);setLow(l.data);setBranches(b.data);setError('')}catch(e){setError(messageOf(e))}},[branch,desde,hasta,global]);useEffect(()=>{void load()},[load,version]);const max=Math.max(1,...sales.map(x=>x.ventas));
  async function exportCsv(){setExporting(true);setError('');try{const params:Record<string,string>={};if(branch)params.sucursal_id=branch;if(desde)params.desde=`${desde}T00:00:00`;if(hasta)params.hasta=`${hasta}T23:59:59`;const response=await api.get('/reportes/ventas.xlsx',{params,responseType:'blob'});const url=URL.createObjectURL(response.data);const a=document.createElement('a');a.href=url;a.download='comandapro_ventas.xlsx';a.click();URL.revokeObjectURL(url)}catch(e){setError(messageOf(e))}finally{setExporting(false)}}
  return <><PageTitle eyebrow="ANÁLISIS · RESULTADOS" title="Reportes de operación" description={global?'Comparativo de ventas por sucursal y periodo, productos líderes y alertas de inventario.':'Resumen de ventas e inventario de tu sucursal.'} action={<><button className="btn btn-secondary" onClick={()=>void load()}><RefreshCw size={16}/> Actualizar</button><button className="btn btn-primary" onClick={()=>void exportCsv()} disabled={exporting}>{exporting?'Exportando…':'Exportar Excel ↓'}</button></>}/><ErrorBanner error={error}/><Card className="filter-card"><div className="filter-row">{global&&<label className="filter-label">Sucursal<select value={branch} onChange={e=>setBranch(e.target.value)}><option value="">Todas las sucursales</option>{branches.map(b=><option value={b.id} key={b.id}>{b.nombre}</option>)}</select></label>}<label className="filter-label">Desde<input type="date" value={desde} onChange={e=>setDesde(e.target.value)}/></label><label className="filter-label">Hasta<input type="date" value={hasta} onChange={e=>setHasta(e.target.value)}/></label><button className="btn btn-secondary filter-apply" onClick={()=>void load()}>Aplicar filtros</button><button className="text-button" onClick={()=>{setBranch('');setDesde('');setHasta('')}}>Limpiar</button></div></Card><div className="dashboard-grid"><Card><div className="card-heading"><div><h2>Ventas por sucursal</h2><p>Pagos de órdenes cobradas en el periodo</p></div></div>{sales.map(x=><div className="bar-row" key={x.sucursal_id}><div className="bar-label"><span>{x.sucursal}</span><strong>{money(x.ventas)}</strong></div><div className="bar-track"><div className="bar-fill" style={{width:`${(x.ventas/max)*100}%`}}/></div><small>{x.pagos} pagos</small></div>)}</Card><Card><div className="card-heading"><div><h2>Productos más vendidos</h2><p>Solo órdenes pagadas de tu sucursal de sesión</p></div></div>{top.length?top.map((x,i)=><div className="top-product" key={x.producto}><span className="rank">{String(i+1).padStart(2,'0')}</span><span className="grow"><strong>{x.producto}</strong><small>{x.unidades} unidades</small></span><strong>{money(x.importe)}</strong></div>):<Empty title="Sin ventas registradas" detail="Los productos aparecerán cuando se cobren órdenes."/>}</Card></div><Card><div className="card-heading"><div><h2>Alertas de stock mínimo</h2><p>Existencias que requieren reposición en la sucursal de sesión</p></div><span className="pill">{low.length} alertas</span></div>{low.length?<div className="table-responsive"><table><thead><tr><th>Insumo</th><th>Existencia</th><th>Stock mínimo</th><th>Prioridad</th></tr></thead><tbody>{low.map(x=><tr key={x.insumo}><td><strong>{x.insumo}</strong></td><td>{x.existencia} {x.unidad}</td><td>{x.stock_minimo} {x.unidad}</td><td><Status value="STOCK_BAJO"/></td></tr>)}</tbody></table></div>:<Empty title="Inventario en nivel saludable" detail="No hay insumos por debajo del mínimo."/>}</Card></>;
}

const AUDIT_LABELS: Record<string,string> = {POST:'CREAR',PUT:'EDITAR',PATCH:'EDITAR',DELETE:'ELIMINAR'};
const AUDIT_ENTITIES = ['orden','platillo','pago','producto','categoria','insumo','mesa','usuario','rol','permiso','sucursal','movimiento_inventario','receta','sesion'];
function AuditPage({version}:{version:number}) {
  const [rows,setRows]=useState<Record<string,unknown>[]>([]);const [users,setUsers]=useState<{id:number;nombre:string}[]>([]);const [error,setError]=useState('');const [accion,setAccion]=useState('');const [entidad,setEntidad]=useState('');const [usuario,setUsuario]=useState('');const [desde,setDesde]=useState('');const [hasta,setHasta]=useState('');
  const load=useCallback(async()=>{try{const params:Record<string,string>={limite:'200'};if(accion)params.accion=accion;if(entidad)params.entidad=entidad;if(usuario)params.usuario_id=usuario;if(desde)params.desde=`${desde}T00:00:00`;if(hasta)params.hasta=`${hasta}T23:59:59`;const r=await api.get('/bitacora',{params});setRows(r.data);setError('')}catch(e){setError(messageOf(e))}},[accion,entidad,usuario,desde,hasta]);
  useEffect(()=>{void load()},[load,version]);
  useEffect(()=>{api.get('/admin/usuarios').then(r=>setUsers(r.data)).catch(()=>setUsers([]))},[]);
  const detail=(r:Record<string,unknown>)=>{const d=(r.datos_json??{}) as {descripcion?:string;ruta?:string};return d.descripcion??d.ruta??''};
  return <><PageTitle eyebrow="TRAZABILIDAD · CONTROL INTERNO" title="Bitácora de auditoría" description="Creaciones, ediciones y eliminaciones registradas automáticamente por la API." action={<button className="btn btn-secondary" onClick={()=>void load()}><RefreshCw size={16}/> Actualizar</button>}/><ErrorBanner error={error}/><Card className="filter-card"><div className="filter-row"><label className="filter-label">Usuario<select value={usuario} onChange={e=>setUsuario(e.target.value)}><option value="">Todos</option>{users.map(u=><option key={u.id} value={u.id}>{u.nombre}</option>)}</select></label><label className="filter-label">Acción<select value={accion} onChange={e=>setAccion(e.target.value)}><option value="">Todas</option><option value="CREAR">Crear</option><option value="EDITAR">Editar</option><option value="ELIMINAR">Eliminar</option><option value="ACCESO">Acceso</option></select></label><label className="filter-label">Entidad<select value={entidad} onChange={e=>setEntidad(e.target.value)}><option value="">Todas</option>{AUDIT_ENTITIES.map(x=><option key={x} value={x}>{x.replaceAll('_',' ')}</option>)}</select></label><label className="filter-label">Desde<input type="date" value={desde} onChange={e=>setDesde(e.target.value)}/></label><label className="filter-label">Hasta<input type="date" value={hasta} onChange={e=>setHasta(e.target.value)}/></label><button className="text-button" onClick={()=>{setUsuario('');setAccion('');setEntidad('');setDesde('');setHasta('')}}>Limpiar</button></div></Card><Card>{rows.length?<div className="table-responsive"><table><thead><tr><th>Fecha</th><th>Usuario</th><th>Acción</th><th>Entidad</th><th>Referencia</th><th>Descripción</th></tr></thead><tbody>{rows.map((r,i)=>{const a=String(r.accion??'');return <tr key={String(r.id??i)}><td>{r.fecha?dateTime(String(r.fecha)):''}</td><td>{String(r.usuario??'—')}</td><td><Status value={AUDIT_LABELS[a]??a}/></td><td>{String(r.entidad??'—').replaceAll('_',' ')}</td><td>{r.entidad_id?`#${String(r.entidad_id)}`:'—'}</td><td>{detail(r)}</td></tr>})}</tbody></table></div>:<Empty title="Sin eventos para estos filtros" detail="Las acciones de escritura aparecerán aquí."/>}</Card></>
}

export default function App() {
  const [user,setUser]=useState<User|null>(null);const [view,setView]=useState('inicio');const [ready,setReady]=useState(false);const [toast,setToast]=useState('');const [version,setVersion]=useState(0);const [socketState,setSocketState]=useState<'connected'|'disconnected'>('disconnected');const [sidebarOpen,setSidebarOpen]=useState(false);const [tokenRevision,setTokenRevision]=useState(0);
  const notify=useCallback((message:string)=>{setToast(message);window.setTimeout(()=>setToast(''),3500)},[]);
  const logoutLocal=useCallback(()=>{setUser(null);setAccessToken(null);setView('inicio');setSocketState('disconnected')},[]);
  const login=useCallback(async(email:string,password:string)=>{const r=await api.post('/auth/login',{correo:email,password});setAccessToken(r.data.access_token);setUser(r.data.usuario);setView('inicio');setVersion(x=>x+1)},[]);
  const logout=useCallback(async()=>{try{await api.post('/auth/logout')}catch{/* local cleanup even if session already expired */}logoutLocal()},[logoutLocal]);
  useEffect(()=>{let mounted=true;async function init(){const token=getAccessToken();if(token){try{const r=await api.get('/auth/me');if(mounted)setUser(r.data)}catch{if(mounted)logoutLocal()}}if(mounted)setReady(true)}void init();const onExpired=()=>logoutLocal();const onTokenRefreshed=()=>setTokenRevision(x=>x+1);window.addEventListener('comandapro:session-expired',onExpired);window.addEventListener('comandapro:token-refreshed',onTokenRefreshed);return()=>{mounted=false;window.removeEventListener('comandapro:session-expired',onExpired);window.removeEventListener('comandapro:token-refreshed',onTokenRefreshed)}},[logoutLocal]);
  useEffect(()=>{const token=getAccessToken();if(!user||!token)return;const socket:Socket=io(window.location.origin,{path:'/socket.io',auth:{token},transports:['websocket','polling']});socket.on('connect',()=>setSocketState('connected'));socket.on('disconnect',()=>setSocketState('disconnected'));for(const event of ['orden_nueva','orden_actualizada','platillo_actualizado'])socket.on(event,(payload)=>{setVersion(v=>v+1);if(event==='orden_nueva')notify(`Nueva comanda para mesa ${payload?.mesa_numero??''}`.trim());else if(event==='platillo_actualizado'&&payload?.estado==='LISTO')notify('Cocina marcó un platillo como listo')});return()=>{socket.disconnect()}},[user?.id,notify,tokenRevision]);
  const has=(key:string)=>!!user?.permisos.includes(key);
  const nav=useMemo(()=>[
    {key:'inicio',label:'Resumen',icon:LayoutDashboard,show:!!user},
    {key:'ordenes',label:'Mesas y órdenes',icon:ClipboardList,show:has('mesas.ver')||has('ordenes.crear')},
    {key:'cocina',label:'Cocina en vivo',icon:ChefHat,show:has('cocina.ver')},
    {key:'caja',label:'Caja y pagos',icon:CircleDollarSign,show:has('pagos.ver')},
    {key:'inventario',label:'Inventario',icon:Boxes,show:has('inventario.ver')},
    {key:'menu',label:'Menú y recetas',icon:Utensils,show:has('productos.crear')||has('recetas.configurar')},
    {key:'seguridad',label:'Usuarios y permisos',icon:ShieldCheck,show:has('usuarios.ver')||has('roles.configurar')},
    {key:'reportes',label:'Reportes',icon:FileBarChart2,show:has('reportes.ver')},
    {key:'bitacora',label:'Bitácora',icon:BookOpen,show:has('bitacora.ver')},
  ],[user]);
  if(!ready)return <div className="boot-screen"><div className="brand"><span className="brand-mark"><Utensils/></span><span>comanda<span className="brand-soft">pro</span></span></div><div className="spinner"/><span>Preparando tu sucursal…</span></div>;
  if(!user)return <Login onLogin={login}/>;
  const active=nav.find(n=>n.key===view&&n.show)??nav.find(n=>n.show)!;
  function renderView(){switch(active.key){case'ordenes':return <OrdersPage user={user!} notify={notify} version={version}/>;case'cocina':return <KitchenPage notify={notify} version={version}/>;case'caja':return <CashierPage notify={notify} version={version}/>;case'inventario':return <InventoryPage user={user!} notify={notify} version={version}/>;case'menu':return <MenuAdmin notify={notify} version={version}/>;case'seguridad':return <SecurityAdmin user={user!} notify={notify} version={version}/>;case'reportes':return <ReportsPage user={user!} version={version}/>;case'bitacora':return <AuditPage version={version}/>;default:return <Dashboard user={user!} onNavigate={setView} version={version}/>}}
  return <div className="app-shell"><aside className={`sidebar ${sidebarOpen?'sidebar-open':''}`}><div className="brand"><span className="brand-mark"><Utensils/></span><span>comanda<span className="brand-soft">pro</span></span></div><div className="branch-card"><span className="branch-pin"><Store size={16}/></span><div><small>ESTÁS EN</small><strong>{user.sucursal}</strong></div><ChevronDown size={15}/></div><div className="nav-label">OPERACIÓN</div><nav>{nav.filter(n=>n.show).map(n=><button key={n.key} className={`nav-item ${active.key===n.key?'active':''}`} onClick={()=>{setView(n.key);setSidebarOpen(false)}}><n.icon size={18}/><span>{n.label}</span>{n.key==='cocina'&&<span className={`live-dot ${socketState==='connected'?'':'offline'}`}/>}</button>)}</nav><div className="sidebar-bottom"><div className="connection-line"><span className={`live-dot ${socketState==='connected'?'':'offline'}`}/><span>{socketState==='connected'?'Actualización en tiempo real':'Reconectando en tiempo real'}</span></div><div className="user-card"><div className="avatar">{user.nombre.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase()}</div><div className="user-info"><strong>{user.nombre}</strong><small>{user.rol}</small></div><button className="icon-button logout-button" title="Cerrar sesión" onClick={()=>void logout()}><LogOut size={17}/></button></div></div></aside><main className="main-area"><header className="topbar"><button className="icon-button mobile-menu" onClick={()=>setSidebarOpen(x=>!x)} aria-label="Abrir menú"><Menu/></button><div className="breadcrumbs"><span>ComandaPro</span><span className="crumb-sep">/</span><strong>{active.label}</strong></div><div className="top-actions"><div className="connection-pill"><span className={`live-dot ${socketState==='connected'?'':'offline'}`}/>{socketState==='connected'?'En vivo':'Sin conexión realtime'}</div><button className="icon-button notification-button" aria-label="Notificaciones" onClick={()=>notify(socketState==='connected'?'Las notificaciones en vivo están activas.':'Intentando reconectar a la sala de sucursal.')}><Bell size={18}/></button><span className="top-avatar">{user.nombre.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase()}</span></div></header><div className="page-content">{renderView()}<footer className="page-footer"><span>ComandaPro · Operación sincronizada</span><span><Activity size={13}/> API protegida · Access token de 15 min</span></footer></div></main>{toast&&<div className="toast"><span className="toast-check">✓</span>{toast}<button className="toast-close" onClick={()=>setToast('')} aria-label="Cerrar notificación"><X size={15}/></button></div>}{sidebarOpen&&<button className="sidebar-scrim" aria-label="Cerrar menú" onClick={()=>setSidebarOpen(false)}/>}</div>;
}
